WITH flattened_attrs AS (SELECT id, customer_id, created_at, coupon_codes, items, attributes, SIZE(attributes) AS num_attributes, TRY_CAST(attributes['weight_kg'] AS DOUBLE) AS weight_kg, ARRAY_MAX(TRANSFORM(items, i -> i.price)) AS max_item_price, AGGREGATE(items, 0D, (acc, i) -> acc + i.qty * i.price, acc -> ROUND(acc, 2)) AS items_total FROM carts WHERE customer_id = 32) SELECT id, created_at, num_attributes, weight_kg, items_total, LAG(num_attributes) OVER (PARTITION BY customer_id ORDER BY num_attributes, id) prev_num_attributes, LEAD(max_item_price) OVER (PARTITION BY customer_id ORDER BY num_attributes, id) next_max_item_price, LAG(max_item_price) OVER (PARTITION BY customer_id ORDER BY num_attributes, id) prev_max_item_price, ROW_NUMBER() OVER (PARTITION BY customer_id ORDER BY num_attributes, id) event_seq, LAG(items_total, 2) OVER (ORDER BY weight_kg, id) prev_items_total FROM flattened_attrs WHERE weight_kg >= 3.8;
